def is_majority(arr, n, x):
    # Find the first occurrence of x
    left = binary_search(arr, x)

    # If x is not present, return False
    if left == -1:
        return False

    # Find the last occurrence of x
    right = binary_search(arr, x, True)

    # Calculate the number of occurrences of x
    count = right - left + 1

    # Check if the count is greater than n/2
    return count > n // 2

def binary_search(arr, x, find_last=False):
    low, high = 0, len(arr) - 1
    result = -1

    while low <= high:
        mid = low + (high - low) // 2

        if arr[mid] == x:
            result = mid
            if find_last:
                low = mid + 1
            else:
                high = mid - 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    return result
