def count_Substrings(s):
    def digit_sum(sub):
        return sum(int(digit) for digit in sub)

    count = 0
    n = len(s)

    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = s[i:j]
            if digit_sum(substring) == len(substring):
                count += 1

    return count
